import os

def print_digit(num):
    if num == 1:
        print("1")
    elif num == 2:
        print("2")
    elif num == 3:
        print("3")
    else:
        print(f"4")

os.system("echo 1 > /dev/null")
os.system("echo 2 > /dev/null")
os.system("echo 3 > /dev/null")
os.system("echo 4 > /dev/null")

